CREATE OR REPLACE FUNCTION public.submit_order_supplement (
  p_order_id uuid,
  p_payload  jsonb
)
  RETURNS TABLE (
    needs_gacha_roll boolean
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$ DECLARE v_user_id uuid; v_store_id character varying; v_status character varying; v_reason character varying; v_affected uuid[]; v_address_id uuid; v_gacha_action text; v_item jsonb; v_item_id uuid; v_new_qty integer; v_old_qty integer; v_product_id uuid; v_owner_id uuid; v_order_number integer; v_store_code character varying; v_needs_roll boolean := false; BEGIN SELECT o.user_id, o.store_id, o.status, o.hold_reason_code, o.hold_affected_item_ids, o.order_number, st.store_code INTO v_user_id, v_store_id, v_status, v_reason, v_affected, v_order_number, v_store_code FROM public.orders o JOIN public.stores st ON st.id = o.store_id WHERE o.id = p_order_id; IF v_user_id IS NULL THEN RAISE EXCEPTION 'order_not_found'; END IF; IF v_user_id <> auth.uid() THEN RAISE EXCEPTION 'not_order_owner'; END IF; IF v_status <> 'on_hold' THEN RAISE EXCEPTION 'invalid_order_state'; END IF; SELECT s.owner_id INTO v_owner_id FROM public.stores s WHERE s.id = v_store_id; IF v_reason = 'address_issue' THEN v_address_id := (p_payload->>'address_id')::uuid; IF v_address_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.user_addresses ua WHERE ua.id = v_address_id AND ua.user_id = v_user_id) THEN RAISE EXCEPTION 'invalid_address'; END IF; UPDATE public.orders o SET shipping_address_id = v_address_id WHERE o.id = p_order_id; ELSIF v_reason = 'line_stock_short' THEN IF p_payload->'items' IS NULL OR jsonb_array_length(p_payload->'items') = 0 THEN RAISE EXCEPTION 'items_required'; END IF; FOR v_item IN SELECT * FROM jsonb_array_elements(p_payload->'items') LOOP v_item_id := (v_item->>'item_id')::uuid; v_new_qty := GREATEST(0, COALESCE((v_item->>'quantity')::integer, 0)); IF NOT (v_item_id = ANY (v_affected)) THEN RAISE EXCEPTION 'item_not_affected'; END IF; SELECT oi.quantity, oi.product_id INTO v_old_qty, v_product_id FROM public.order_items oi WHERE oi.id = v_item_id AND oi.order_id = p_order_id; IF v_product_id IS NULL THEN RAISE EXCEPTION 'invalid_item'; END IF; IF v_new_qty >= v_old_qty THEN RAISE EXCEPTION 'quantity_must_decrease'; END IF; IF v_new_qty = 0 THEN UPDATE public.products p SET stock_quantity = p.stock_quantity + v_old_qty, updated_at = now() WHERE p.id = v_product_id; DELETE FROM public.order_items oi WHERE oi.id = v_item_id; ELSE UPDATE public.products p SET stock_quantity = p.stock_quantity + (v_old_qty - v_new_qty), updated_at = now() WHERE p.id = v_product_id; UPDATE public.order_items oi SET quantity = v_new_qty WHERE oi.id = v_item_id; END IF; END LOOP; PERFORM public._recalculate_order_totals(p_order_id); ELSIF v_reason = 'gacha_prize_oos' THEN v_gacha_action := p_payload->>'gacha_action'; IF v_gacha_action NOT IN ('reroll', 'forfeit') THEN RAISE EXCEPTION 'invalid_gacha_action'; END IF; PERFORM public._restore_gacha_roll(p_order_id); v_needs_roll := (v_gacha_action = 'reroll'); ELSIF v_reason = 'other' THEN RAISE EXCEPTION 'supplement_not_allowed'; ELSE RAISE EXCEPTION 'invalid_reason_code'; END IF; IF NOT EXISTS (SELECT 1 FROM public.order_items oi WHERE oi.order_id = p_order_id) THEN RAISE EXCEPTION 'no_valid_items'; END IF; UPDATE public.orders o SET status = 'awaiting_accept', supplement_submitted_at = now(), hold_reason_code = NULL, hold_reason_text = NULL, hold_requested_at = NULL, hold_affected_item_ids = NULL WHERE o.id = p_order_id; PERFORM public._enqueue_order_notification(v_owner_id, p_order_id, 'order_supplement_submitted', '수정 주문 접수', format('주문 %s-%s 수정이 접수됐어요. 확인해 주세요.', v_store_code, v_order_number)); RETURN QUERY SELECT v_needs_roll; END; $function$;

GRANT EXECUTE ON FUNCTION "public"."submit_order_supplement"(uuid, jsonb) TO "authenticated";

REVOKE ALL ON FUNCTION "public"."submit_order_supplement"(uuid, jsonb) FROM "postgres";

GRANT EXECUTE ON FUNCTION "public"."submit_order_supplement"(uuid, jsonb) TO "postgres";

REVOKE ALL ON FUNCTION "public"."submit_order_supplement"(uuid, jsonb) FROM PUBLIC, "anon", "service_role";
